sys_transform_entry.source_script:
answer = (function transformEntry(source) {
    const actionTaken = source.u_action_s__taken_by_manager.toString().trim(); //some entries are " ", we need to remove them

    //only return if there's an action
    if (actionTaken !== null && actionTaken !== '' && actionTaken !== '0') {
        if (actionTaken.length > 300) {
            return actionTaken.substring(0, 299);
        } else {
            return actionTaken;
        }
    }

    return 'NULL'; //If we return nothing it calls "toString" and will add "undefined" in the short description, this leaves it empty, then we use an onBefore script in the transform with the same conditions and if it's empty we do: ignore = true;
})(source);
